-- ROOT ONLY after reviewed candidate apply. Synthetic workspace/profile/expired session only.
-- No real QA authority changes, provider calls, files, reminders, signatures or filings.
BEGIN;SET LOCAL lock_timeout='3s';SET LOCAL statement_timeout='30s';SET LOCAL idle_in_transaction_session_timeout='60s';
CREATE TEMP TABLE company_private_results(label text PRIMARY KEY,passed boolean)ON COMMIT DROP;GRANT INSERT,SELECT ON company_private_results TO authenticated;
CREATE FUNCTION pg_temp.company_private_assert(ok boolean,label text)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'company_private_assert_failed:%',label;END IF;INSERT INTO pg_temp.company_private_results VALUES(label,true);END$$;
DO $qa$DECLARE
 executor name:=current_user;known_ws constant uuid:='053a5656-b19b-48a4-8721-65c4674f647c';actor constant uuid:='21a04e78-e3b1-448e-8517-47aad25dd5da';account constant uuid:='2ba5b8e3-4fe9-4ec7-a3bf-7f616fcf07fd';
 ws constant uuid:='a3c01505-1015-4000-8000-000000000001';other_profile constant uuid:='a3c01505-1015-4000-8000-000000000002';nonce constant uuid:='a3c01505-1015-4000-8000-000000000003';cancel_nonce constant uuid:='a3c01505-1015-4000-8000-000000000004';edit_nonce constant uuid:='a3c01505-1015-4000-8000-000000000005';role_nonce constant uuid:='a3c01505-1015-4000-8000-000000000006';deadline_nonce constant uuid:='a3c01505-1015-4000-8000-000000000007';expired_sid constant uuid:='a3c01505-1015-4000-8000-000000000008';archive_nonce constant uuid:='a3c01505-1015-4000-8000-000000000009';restore_nonce constant uuid:='a3c01505-1015-4000-8000-000000000010';admin_nonce constant uuid:='a3c01505-1015-4000-8000-000000000012';
 sid uuid;c jsonb;r jsonb;receipt jsonb;edit_receipt jsonb;replay jsonb;role_receipt jsonb;deadline_receipt jsonb;payload jsonb;edited jsonb;denied boolean;member_role text;before_rows integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM zoi.workspaces w JOIN zoi.workspace_members m ON m.workspace_id=w.id JOIN zoi.user_profiles up ON up.id=m.profile_id JOIN auth.users au ON au.id=up.auth_user_id WHERE w.id=known_ws AND w.name='Zoi isolated QA 2026-09-30'AND w.owner_profile_id=actor AND m.profile_id=actor AND m.role='owner'AND up.auth_user_id=account AND au.email_confirmed_at IS NOT NULL AND au.deleted_at IS NULL AND NOT coalesce(au.is_anonymous,false)AND(au.banned_until IS NULL OR au.banned_until<=clock_timestamp()))THEN RAISE EXCEPTION 'dedicated_qa_authority_unavailable';END IF;
 SELECT id INTO sid FROM auth.sessions WHERE user_id=account AND(not_after IS NULL OR not_after>clock_timestamp())ORDER BY created_at DESC NULLS LAST LIMIT 1;IF sid IS NULL THEN RAISE EXCEPTION 'dedicated_qa_current_session_unavailable';END IF;
 IF EXISTS(SELECT 1 FROM zoi.workspaces WHERE id=ws)OR EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id=other_profile)OR EXISTS(SELECT 1 FROM auth.sessions WHERE id=expired_sid)OR EXISTS(SELECT 1 FROM zoi.company_private_requests WHERE request_id IN(nonce,cancel_nonce,edit_nonce,role_nonce,deadline_nonce,archive_nonce,restore_nonce,admin_nonce))THEN RAISE EXCEPTION 'company_private_fixture_collision';END IF;
 INSERT INTO zoi.user_profiles(id,display_name)VALUES(other_profile,'Rollback-only Company private synthetic profile');INSERT INTO zoi.workspaces(id,name,kind,owner_profile_id,created_by_auth)VALUES(ws,'Rollback-only private Company 20261015','business',actor,account);INSERT INTO auth.sessions(id,user_id,created_at,updated_at,not_after)VALUES(expired_sid,account,clock_timestamp(),clock_timestamp(),clock_timestamp()-interval'1 minute');
 PERFORM pg_temp.company_private_assert(NOT EXISTS(SELECT 1 FROM zoi.workspace_members WHERE workspace_id=ws),'synthetic_workspace_real_owner_without_member');
 PERFORM set_config('request.jwt.claim.sub',account::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid)::text,true);EXECUTE'SET LOCAL ROLE authenticated';
 c:=public.ops_record_save(ws,'company','{"title":"Rollback Company governance"}',null,0);
 payload:=jsonb_build_object('id',null,'expected_version',0,'kind','minute','data',jsonb_build_object('title','Private meeting fixture','local_at','2026-10-15T12:00','timezone','Europe/Athens','participants','Synthetic participants','body','Private synthetic decision for rollback only'));
 receipt:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,nonce,'save',payload);replay:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,nonce,'save',payload);PERFORM pg_temp.company_private_assert(receipt=replay AND receipt->>'state'='saved'AND receipt->>'version'='1','owner_fallback_canonical_create_exact_lost_response_replay');
 r:=public.company_private_list(ws,(c#>>'{record,id}')::uuid,null,false,32,0);PERFORM pg_temp.company_private_assert(r->>'schema_version'='1'AND r->>'account'=account::text AND r#>>'{company,id}'=c#>>'{record,id}'AND r->>'total'='1','private_list_exact_current_scope_and_total');
 r:=public.company_private_get(ws,(c#>>'{record,id}')::uuid,(receipt->>'record_id')::uuid,null);PERFORM pg_temp.company_private_assert(r#>>'{record,data,body}'='Private synthetic decision for rollback only'AND jsonb_array_length(r->'history')=1,'private_reopen_and_immutable_version_history');
 edited:=jsonb_set(jsonb_set(jsonb_set(payload,'{id}',receipt->'record_id'),'{expected_version}','1'),'{data,body}','"Updated private synthetic decision"');edit_receipt:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,edit_nonce,'save',edited);PERFORM pg_temp.company_private_assert(edit_receipt->>'version'='2','private_edit_advances_canonical_version');
 denied:=false;BEGIN PERFORM public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,cancel_nonce,'save',edited);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='company_private_version_conflict';END;PERFORM pg_temp.company_private_assert(denied,'stale_private_form_cannot_overwrite_newer_version');
 r:=public.company_private_request(ws,(c#>>'{record,id}')::uuid,cancel_nonce,false);PERFORM pg_temp.company_private_assert(r->>'state'='missing','failed_cas_has_no_saved_receipt');r:=public.company_private_request(ws,(c#>>'{record,id}')::uuid,cancel_nonce,true);PERFORM pg_temp.company_private_assert(r->>'state'='cancelled','unsaved_nonce_can_be_cancelled');
 denied:=false;BEGIN PERFORM public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,cancel_nonce,'save',payload);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='company_private_request_cancelled';END;PERFORM pg_temp.company_private_assert(denied,'cancel_tombstone_refuses_delayed_mutation');
 denied:=false;BEGIN PERFORM public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,nonce,'save',jsonb_set(payload,'{data,body}','"Changed retry"'));EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='company_private_request_conflict';END;PERFORM pg_temp.company_private_assert(denied,'same_nonce_different_private_content_refused');
 role_receipt:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,role_nonce,'save','{"id":null,"expected_version":0,"kind":"role","data":{"title":"Chair","person":"Synthetic Person","body":"Internal responsibility only","start_date":"2026-10-15","end_date":null}}');deadline_receipt:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,deadline_nonce,'save','{"id":null,"expected_version":0,"kind":"deadline","data":{"title":"Internal review","local_at":"2026-11-01T17:00","timezone":"Europe/Athens","person":"Synthetic Person","body":"Manual internal date only","status":"pending"}}');PERFORM pg_temp.company_private_assert(role_receipt->>'kind'='role'AND deadline_receipt->>'kind'='deadline','named_role_and_internal_deadline_persist_without_external_action');
 r:=public.ops_records_list(ws,null,false);PERFORM pg_temp.company_private_assert(position('Private synthetic decision'in r::text)=0 AND position('Synthetic Person'in r::text)=0,'private_text_not_in_ordinary_operations_projection');
 denied:=false;BEGIN PERFORM 1 FROM zoi.company_private_records;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;PERFORM pg_temp.company_private_assert(denied,'browser_direct_private_table_access_denied');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM pg_temp.company_private_assert(NOT EXISTS(SELECT 1 FROM zoi.workspace_members WHERE workspace_id=ws),'named_company_role_does_not_grant_membership');
 FOREACH member_role IN ARRAY ARRAY['viewer','editor','owner']LOOP
 UPDATE zoi.workspaces SET owner_profile_id=other_profile WHERE id=ws;INSERT INTO zoi.workspace_members(workspace_id,profile_id,role)VALUES(ws,actor,member_role);EXECUTE'SET LOCAL ROLE authenticated';
 denied:=false;BEGIN PERFORM public.company_private_get(ws,(c#>>'{record,id}')::uuid,(receipt->>'record_id')::uuid,null);EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='company_permission_denied';END;PERFORM pg_temp.company_private_assert(denied,'private_record_denies_'||member_role);
 denied:=false;BEGIN PERFORM public.company_private_request(ws,(c#>>'{record,id}')::uuid,nonce,false);EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='company_permission_denied';END;PERFORM pg_temp.company_private_assert(denied,'private_receipt_denies_'||member_role);
 EXECUTE format('SET LOCAL ROLE %I',executor);DELETE FROM zoi.workspace_members WHERE workspace_id=ws;UPDATE zoi.workspaces SET owner_profile_id=actor WHERE id=ws;
 END LOOP;
 UPDATE zoi.workspaces SET owner_profile_id=other_profile WHERE id=ws;INSERT INTO zoi.workspace_members(workspace_id,profile_id,role)VALUES(ws,actor,'admin');EXECUTE'SET LOCAL ROLE authenticated';r:=public.company_private_list(ws,(c#>>'{record,id}')::uuid,null,false,32,0);PERFORM pg_temp.company_private_assert(r->>'total'='3','current_admin_private_read_access');r:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,admin_nonce,'save','{"id":null,"expected_version":0,"kind":"role","data":{"title":"Admin responsibility","person":"Synthetic Admin","body":"Internal manual record","start_date":null,"end_date":null}}');PERFORM pg_temp.company_private_assert(r->>'state'='saved','current_admin_private_write_access');EXECUTE format('SET LOCAL ROLE %I',executor);DELETE FROM zoi.workspace_members WHERE workspace_id=ws;UPDATE zoi.workspaces SET owner_profile_id=actor WHERE id=ws;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',expired_sid)::text,true);EXECUTE'SET LOCAL ROLE authenticated';denied:=false;BEGIN PERFORM public.company_private_request(ws,(c#>>'{record,id}')::uuid,nonce,false);EXCEPTION WHEN insufficient_privilege THEN denied:=SQLERRM='suite_session_unavailable';END;PERFORM pg_temp.company_private_assert(denied,'expired_session_cannot_recover_successful_private_receipt');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',account,'role','authenticated','session_id',sid)::text,true);EXECUTE'SET LOCAL ROLE authenticated';
 replay:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,archive_nonce,'archive',jsonb_build_object('id',role_receipt->'record_id','expected_version',1));PERFORM pg_temp.company_private_assert(replay->>'version'='2','archive_preserves_new_private_version');replay:=public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,restore_nonce,'restore',jsonb_build_object('id',role_receipt->'record_id','expected_version',2));PERFORM pg_temp.company_private_assert(replay->>'version'='3','explicit_restore_preserves_new_private_version');
 EXECUTE format('SET LOCAL ROLE %I',executor);UPDATE zoi.ops_records SET archived_at=clock_timestamp()WHERE id=(c#>>'{record,id}')::uuid;EXECUTE'SET LOCAL ROLE authenticated';
 r:=public.company_private_get(ws,(c#>>'{record,id}')::uuid,(receipt->>'record_id')::uuid,null);PERFORM pg_temp.company_private_assert(r#>>'{record,version}'='2','archived_company_retains_authorized_private_read_history');
 denied:=false;BEGIN PERFORM public.company_private_mutate(ws,(c#>>'{record,id}')::uuid,'a3c01505-1015-4000-8000-000000000011','save',payload);EXCEPTION WHEN raise_exception THEN denied:=SQLERRM='company_private_company_archived';END;PERFORM pg_temp.company_private_assert(denied,'archived_company_refuses_new_private_mutation');
 EXECUTE format('SET LOCAL ROLE %I',executor);PERFORM pg_temp.company_private_assert((SELECT owner_profile_id=actor FROM zoi.workspaces WHERE id=known_ws)AND(SELECT role='owner'FROM zoi.workspace_members WHERE workspace_id=known_ws AND profile_id=actor)AND(SELECT not_after IS NULL OR not_after>clock_timestamp()FROM auth.sessions WHERE id=sid AND user_id=account),'real_qa_authority_and_session_unchanged');
END $qa$;
SELECT label,passed FROM company_private_results ORDER BY label;
ROLLBACK;
SELECT jsonb_build_object('rollback_completed',true,'workspace_absent',NOT EXISTS(SELECT 1 FROM zoi.workspaces WHERE id='a3c01505-1015-4000-8000-000000000001'),'profile_absent',NOT EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id='a3c01505-1015-4000-8000-000000000002'),'session_absent',NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id='a3c01505-1015-4000-8000-000000000008'),'canonical_company_absent',NOT EXISTS(SELECT 1 FROM zoi.ops_records WHERE workspace_id='a3c01505-1015-4000-8000-000000000001'),'private_records_absent',NOT EXISTS(SELECT 1 FROM zoi.company_private_records WHERE workspace_id='a3c01505-1015-4000-8000-000000000001'),'private_versions_absent',NOT EXISTS(SELECT 1 FROM zoi.company_private_versions WHERE workspace_id='a3c01505-1015-4000-8000-000000000001'),'private_requests_absent',NOT EXISTS(SELECT 1 FROM zoi.company_private_requests WHERE workspace_id='a3c01505-1015-4000-8000-000000000001'),'canonical_audit_absent',NOT EXISTS(SELECT 1 FROM zoi.ops_audit WHERE workspace_id='a3c01505-1015-4000-8000-000000000001'),'provider_calls',0,'automated_reminders',0,'legal_filing_or_signature',false);
